interface User { name?: string | null; email?: string | null }
function updateUser(id: string, changes: Partial<User>) {
  const user = db.find(id);
  if (!user) throw new Error('not found');
  if (changes.name !== undefined) user.name = changes.name;
  if (changes.email !== undefined) user.email = changes.email;
  db.save(user);
}

// updateUser('1', { name: null }) intends deletion of name field

// Version A: returns raw Response to callers
async function fetchUserA(id: string): Promise<Response> {
  return fetch(`/users/${id}`);
}

// Version B: normalizes and returns explicit result object
type UserResult = { ok: true; data: User } | { ok: false; error: string };
async function fetchUserB(id: string): Promise<UserResult> {
  const res = await fetch(`/users/${id}`);
  if (!res.ok) return { ok: false, error: res.statusText };
  return { ok: true, data: await res.json() };
}
